    except Exception:pass
    left=until(lambda:find_auto(fw,"LeftFiles"),"LeftFiles missing")
    rows=until(lambda:artwork_ready(left),"artwork not ready",30)
    mode=scroll_to(rows[targets[-1]][0],left)
    time.sleep(1.5)
    print("FLY_SCROLL_MODE",mode,flush=True)
    for t in targets:
        item,_=rows[t];r=item.rectangle()
        print("FLY_SCROLL_VISUAL",repr(t),r.left,r.top,r.width(),r.height(),flush=True)
