        item,_=erows[t];r=item.rectangle()
        print("EXPLORER_SCROLL_VISUAL",repr(t),r.left,r.top,r.width(),r.height(),flush=True)
    print("EXPLORER_SCREENSHOT_BEGIN",flush=True);print(shot_b64(ew),flush=True);print("EXPLORER_SCREENSHOT_END",flush=True)
finally:
